//! The BAGZ demo web app, embedded in Rust (pyCrust).
//!
//! `bundle.rs` holds the built page, script, styles and brand art byte for byte (generated by
//! `scripts/embed_web.py`). This crate serves them (`cargo run -p bagz-web --bin serve`) or writes
//! them out as a static site (`cargo run -p bagz-web --bin export -- dist`) for deployment.

mod bundle;

pub use bundle::FILES;

/// One embedded file.
#[derive(Debug, Clone, Copy)]
pub struct Asset {
    pub path: &'static str,
    pub content_type: &'static str,
    pub sha256: &'static str,
    pub body: &'static str,
}

/// All embedded files.
pub fn assets() -> impl Iterator<Item = Asset> {
    FILES
        .iter()
        .map(|(path, content_type, sha256, body)| Asset {
            path,
            content_type,
            sha256,
            body,
        })
}

/// Resolve a request path. `/` and unknown app routes fall back to `index.html` (single-page app).
pub fn resolve(path: &str) -> Asset {
    let p = path.split(['?', '#']).next().unwrap_or("/");
    assets()
        .find(|a| a.path == p)
        .or_else(|| assets().find(|a| a.path == "/index.html"))
        .expect("index.html is embedded")
}

/// Job ids in the embedded catalog that the bundled app does not mention (should be empty).
pub fn catalog_gaps() -> Vec<String> {
    let js: String = assets()
        .filter(|a| a.path.ends_with(".js"))
        .map(|a| a.body)
        .collect();
    bagz_core::Catalog::bundled()
        .map(|c| {
            c.jobs()
                .iter()
                .filter(|j| !js.contains(j.title.as_str()))
                .map(|j| j.id.clone())
                .collect()
        })
        .unwrap_or_else(|_| vec!["catalog failed to load".into()])
}
